import {
  ChangeDetectionStrategy,
  Component,
  ElementRef,
  effect,
  input,
  output,
  viewChild,
} from '@angular/core';
import { isDevMode } from '@angular/core';

import { UI_COPY } from '../core/i18n/ui-copy';
import type { CountryCode } from '../core/models';

type PanelState = 'loading' | 'empty' | 'error';

@Component({
  selector: 'app-state-panel',
  templateUrl: './state-panel.html',
  styleUrl: './state-panel.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class StatePanelComponent {
  readonly state = input.required<PanelState>();
  readonly message = input<string | null>(null);
  readonly country = input<CountryCode>('CO');
  readonly otherCountryPath = input('/cl/quote');
  readonly retry = output<void>();

  protected readonly copy = UI_COPY;
  protected readonly showDetails = isDevMode();
  private readonly heading = viewChild<ElementRef<HTMLElement>>('panelHeading');

  constructor() {
    effect(() => {
      const state = this.state();
      const heading = this.heading();
      if (state !== 'loading' && heading) {
        queueMicrotask(() => heading.nativeElement.focus());
      }
    });
  }

  protected otherCountryLabel(): string {
    return UI_COPY.otherCountry[this.country()];
  }
}

@switch (state()) {
  @case ('loading') {
    <section class="panel panel--loading" aria-busy="true" aria-live="polite">
      <span class="sr-only">{{ copy.loading }}</span>
      <div class="skeleton skeleton--wide"></div>
      <div class="skeleton"></div>
      <div class="skeleton"></div>
      <div class="skeleton skeleton--short"></div>
    </section>
  }
  @case ('empty') {
    <section class="panel" role="status">
      <h2 #panelHeading tabindex="-1" class="panel__title">{{ copy.emptyTitle }}</h2>
      <p class="panel__body">{{ copy.emptyBody }}</p>
      <div class="panel__actions">
        <button class="button button--primary" type="button" (click)="retry.emit()">
          {{ copy.retry }}
        </button>
        <a class="button button--ghost" [href]="otherCountryPath()">{{ otherCountryLabel() }}</a>
      </div>
    </section>
  }
  @case ('error') {
    <section class="panel panel--error" role="alert">
      <h2 #panelHeading tabindex="-1" class="panel__title">{{ copy.errorTitle }}</h2>
      <p class="panel__body">{{ copy.errorBody }}</p>
      @if (showDetails && message()) {
        <p class="panel__detail">{{ message() }}</p>
      }
      <div class="panel__actions">
        <button class="button button--primary" type="button" (click)="retry.emit()">
          {{ copy.retry }}
        </button>
      </div>
    </section>
  }
}

