1: import { DestroyRef, Injectable, inject, isDevMode, signal, computed } from '@angular/core';
2: import { HttpErrorResponse } from '@angular/common/http';
3: import { Subscription, debounceTime, firstValueFrom, forkJoin } from 'rxjs';
4: 
5: import { CatalogueApi } from '../../core/catalogue/catalogue.api';
6: import { CountryContextService } from '../../core/country/country-context.service';
7: import type {
8:   CatalogueStatus,
9:   CountryCode,
10:   CountryConfig,
11:   FormFieldConfig,
12:   FormValue,
13:   PersistedWizardStateV1,
14:   WizardFormGroup,
15:   WizardStep,
16: } from '../../core/models';
17: import { WizardPersistenceService } from '../../core/persistence/wizard-persistence.service';
18: import { DynamicFormFactory, coerceDraftValue } from './dynamic-form.factory';
19: 
20: @Injectable({ providedIn: 'root' })
21: export class WizardStore {
22:   private readonly catalogue = inject(CatalogueApi);
23:   private readonly context = inject(CountryContextService);
24:   private readonly persistence = inject(WizardPersistenceService);
25:   private readonly factory = inject(DynamicFormFactory);
26:   private readonly destroyRef = inject(DestroyRef);
27: 
28:   private readonly fieldsSignal = signal<readonly FormFieldConfig[]>([]);
29:   private readonly configSignal = signal<CountryConfig | null>(null);
30:   private readonly statusSignal = signal<CatalogueStatus>('idle');
31:   private readonly errorMessageSignal = signal<string | null>(null);
32:   private readonly formSignal = signal<WizardFormGroup | null>(null);
33:   private readonly submittedSignal = signal(false);
34:   private readonly restoredSignal = signal(false);
35:   private readonly selectedPlanSignal = signal<string | null>(null);
36:   private readonly activeCountrySignal = signal<CountryCode | null>(null);
37: 
38:   private changes: Subscription | null = null;
39:   private activeLoad: { readonly country: CountryCode; readonly promise: Promise<void> } | null = null;
40: 
41:   readonly fields = this.fieldsSignal.asReadonly();
42:   readonly countryConfig = this.configSignal.asReadonly();
43:   readonly status = this.statusSignal.asReadonly();
44:   readonly errorMessage = this.errorMessageSignal.asReadonly();
45:   readonly form = this.formSignal.asReadonly();
46:   readonly submitted = this.submittedSignal.asReadonly();
47:   readonly restoredFromDraft = this.restoredSignal.asReadonly();
48:   readonly selectedPlanDocumentId = this.selectedPlanSignal.asReadonly();
49: 
50:   readonly isReady = computed<boolean>(() => this.statusSignal() === 'ready' && this.formSignal() !== null);
51: 
52:   readonly errorCount = computed<number>(() => {
53:     const form = this.formSignal();
54:     if (!this.submittedSignal() || !form) {
55:       return 0;
56:     }
57:     return Object.values(form.controls).reduce((count, control) => count + (control.invalid ? 1 : 0), 0);
58:   });
59: 
60:   constructor() {
61:     this.destroyRef.onDestroy(() => this.changes?.unsubscribe());
62:   }
63: 
64:   /** Reuses an in-flight/resolved load for the same country to avoid duplicate requests. */
65:   load(country: CountryCode): Promise<void> {
66:     if (this.activeLoad?.country === country) {
67:       return this.activeLoad.promise;
68:     }
69:     const promise = this.startLoad(country);
70:     this.activeLoad = { country, promise };
71:     return promise;
72:   }
73: 
74:   retry(): Promise<void> {
75:     this.activeLoad = null;
76:     return this.load(this.activeCountrySignal() ?? this.context.country());
77:   }
78: 
79:   persist(step: WizardStep): void {
80:     const form = this.formSignal();
81:     const country = this.activeCountrySignal() ?? this.context.country();
82:     if (!form || this.statusSignal() !== 'ready') {
83:       return;
84:     }
85: 
86:     const step1: Record<string, FormValue> = {};
87:     for (const field of this.fieldsSignal()) {
88:       const control = form.controls[field.key];
89:       step1[field.key] = control
90:         ? coerceDraftValue(field, control.value)
91:         : this.factory.defaultValue(field);
92:     }
93: 
94:     const state: PersistedWizardStateV1 = {
95:       schemaVersion: 1,
96:       country,
97:       savedAt: new Date().toISOString(),
98:       step,
99:       step1,
100:       selectedPlanDocumentId: this.selectedPlanSignal(),
101:     };
102:     this.persistence.save(state);
103:   }
104: 
105:   patchValues(values: Readonly<Record<string, FormValue>>): void {
106:     const form = this.formSignal();
107:     if (!form) {
108:       return;
109:     }
110:     for (const field of this.fieldsSignal()) {
111:       const control = form.controls[field.key];
112:       const value = values[field.key];
113:       if (control && value !== undefined) {
114:         control.setValue(coerceDraftValue(field, value));
115:       }
116:     }
117:   }
118: 
119:   markSubmitted(): void {
120:     this.submittedSignal.set(true);
121:   }
122: 
123:   isLoadedFor(country: CountryCode): boolean {
124:     return (
125:       this.activeCountrySignal() === country &&
126:       this.statusSignal() === 'ready' &&
127:       this.formSignal() !== null
128:     );
129:   }
130: 
131:   reset(country: CountryCode): void {
132:     this.changes?.unsubscribe();
133:     this.changes = null;
134:     this.activeLoad = null;
135:     this.persistence.clear(country);
136:     this.activeCountrySignal.set(null);
137:     this.fieldsSignal.set([]);
138:     this.configSignal.set(null);
139:     this.formSignal.set(null);
140:     this.statusSignal.set('idle');
141:     this.errorMessageSignal.set(null);
142:     this.submittedSignal.set(false);
143:     this.restoredSignal.set(false);
144:     this.selectedPlanSignal.set(null);
145:   }
146: 
147:   private async startLoad(country: CountryCode): Promise<void> {
148:     this.changes?.unsubscribe();
149:     this.changes = null;
150:     this.activeCountrySignal.set(country);
151:     this.statusSignal.set('loading');
152:     this.errorMessageSignal.set(null);
153:     this.submittedSignal.set(false);
154:     this.restoredSignal.set(false);
155: 
156:     try {
157:       const { fields, config } = await firstValueFrom(
158:         forkJoin({
159:           fields: this.catalogue.getFormFields(country),
160:           config: this.catalogue.getCountryConfig(country),
161:         }),
162:       );
163: 
164:       this.fieldsSignal.set(fields);
165:       this.configSignal.set(config);
166: 
167:       if (fields.length === 0) {
168:         this.formSignal.set(null);
169:         this.selectedPlanSignal.set(null);
170:         this.statusSignal.set('empty');
171:         return;
172:       }
173: 
174:       const draft = this.persistence.load(country);
175:       const values: Record<string, FormValue> = {};
176:       for (const field of fields) {
177:         const raw = draft?.step1[field.key];
178:         values[field.key] = raw === undefined ? this.factory.defaultValue(field) : coerceDraftValue(field, raw);
179:       }
180: 
181:       const form = this.factory.createForm(fields, values);
182:       this.formSignal.set(form);
183:       this.selectedPlanSignal.set(draft?.selectedPlanDocumentId ?? null);
184: 
185:       const hasRestoredValues = Boolean(draft && Object.keys(draft.step1).length > 0);
186:       if (hasRestoredValues) {
187:         form.markAllAsTouched();
188:         this.restoredSignal.set(true);
189:       }
190:       form.updateValueAndValidity({ emitEvent: false });
191:       this.statusSignal.set('ready');
192: 
193:       this.changes = form.valueChanges.pipe(debounceTime(400)).subscribe(() => this.persist('policyholder'));
194:     } catch (error: unknown) {
195:       this.errorMessageSignal.set(this.describeError(error));
196:       this.statusSignal.set('error');
197:     }
198:   }
199: 
200:   private describeError(error: unknown): string | null {
201:     if (!isDevMode()) {
202:       return null;
203:     }
204:     if (error instanceof HttpErrorResponse) {
205:       return `HTTP ${error.status} ${error.statusText}`.trim();
206:     }
207:     return error instanceof Error ? error.message : null;
208:   }
209: }

